import{_ as e,o as s,c as n,a3 as t}from"./chunks/framework.B9qR_F1m.js";const k=JSON.parse('{"title":"ripeat","titleTemplate":"Set up a machine from a list. Undo it safely.","description":"","frontmatter":{"layout":"home","title":"ripeat","titleTemplate":"Set up a machine from a list. Undo it safely.","hero":{"text":"Set up any machine from a list of tools, and undo it safely.","tagline":"ripeat shows the plan and its risk, asks before it changes anything, and keeps a journal so every run can be rolled back."},"features":[{"icon":"🔍","title":"Look before it changes anything","details":"<code>plan</code> shows what would happen, in order and why. <code>assess</code> rates the risk in plain rules, with reasons. Nothing is installed until you say yes.","link":"/assess","linkText":"How risk is rated"},{"icon":"↩️","title":"Every run can be undone","details":"ripeat writes a journal before it acts. <code>rollback</code> undoes a run newest step first, and never removes a tool that was already on your machine.","link":"/install-and-rollback","linkText":"Install and rollback"},{"icon":"📋","title":"A list is all you write","details":"Name the tools you want, or just type <code>ripeat</code> and it asks. Recipes say how, for each system, through the package managers you already have, or a checked download.","link":"/profiles","linkText":"Profiles"},{"icon":"🔎","title":"Install by name","details":"Ask for an app ripeat does not know yet. It looks in Homebrew, apt, dnf, pacman, winget, the Microsoft Store, Chocolatey, Scoop, Snap, Flatpak and GitHub, drafts the recipe, and saves it only if you agree.","link":"/find-and-add","linkText":"Find and add"},{"icon":"🤖","title":"Works with your AI assistant","details":"Claude, Codex and others can plan, rate and prepare recipes through MCP. By default they cannot install; you stay the one who says yes.","link":"/mcp","linkText":"Use it from an assistant"},{"icon":"🏢","title":"Safe to share with a team","details":"Share a list or a recipe pack, and let an administrator set rules that nothing can override.","link":"/taps","linkText":"Recipe packs"}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),i={name:"index.md"};function l(o,a,r,p,h,d){return s(),n("div",null,[...a[0]||(a[0]=[t(`<div class="home-tour"><h2 id="a-first-look" tabindex="-1">A first look <a class="header-anchor" href="#a-first-look" aria-label="Permalink to &quot;A first look&quot;">​</a></h2><p>These commands only look. They change nothing.</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ ripeat plan git node ripgrep</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Plan (darwin):</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  1. git          -               user   already on this machine, will be left alone</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  2. node         -               user   already on this machine, will be left alone</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  3. ripgrep      github_release  user   requested</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ ripeat assess ripgrep</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Risk: MEDIUM   1 to install</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  RISK      TOOL     HOW             WHY</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  MEDIUM    ripgrep  github_release  requested</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">                     - downloads a program from a third party: its SHA-256 is</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">                       verified, but ripeat cannot vouch for the project itself</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">What would run, without administrator rights:</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  download the latest BurntSushi/ripgrep release for this machine, check its SHA-256, ...</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Can it be undone? Yes: \`ripeat rollback\` removes what this run installs</span></span></code></pre></div><p>When you are ready, <code>ripeat install ripgrep</code> shows the plan again, asks <code>Install 1 tool as shown above? [y/N]</code>, and only then changes anything. <code>ripeat rollback</code> undoes it.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><strong>New here?</strong> <a href="/getting-started">Getting started</a>, then <a href="/architecture">how ripeat works</a>.</li><li><strong>Looking for a command?</strong> The <a href="/commands">command reference</a> lists every one, and what it changes.</li><li><strong>Using an AI assistant?</strong> <a href="/mcp">ripeat as an MCP server</a> explains what an assistant can and cannot do.</li><li><strong>Setting it up for a team?</strong> <a href="/taps">Recipe packs</a>, the <a href="/admin-policy">administrator policy</a> and <a href="/privileges">admin rights</a>.</li><li><strong>Wondering what has been tested where?</strong> <a href="/platforms">What has been verified</a>.</li></ul></div>`,1)])])}const g=e(i,[["render",l]]);export{k as __pageData,g as default};
